namespace ghidra.app.plugin.core.debug.service.tracermi;




using ghidra.debug.api.tracermi;
using ghidra.debug.api.tracermi.TraceRmiServiceListener;
using ghidra.util.exception;

public class DefaultTraceRmiAcceptor : AbstractTraceRmiListener, TraceRmiAcceptor {
	private bool cancelled = false;

	public DefaultTraceRmiAcceptor(TraceRmiPlugin plugin, SocketAddress address) : base(plugin, address)
    {
	}

	/* @Override */
	protected void startServiceLoop() {
		// Don't. Instead, client calls accept()
	}

	/* @Override */
	protected void bind()
    {
		socket.bind(address, 1);
		plugin.addAcceptor(this);
	}

	/* @Override */
	protected ConnectMode getConnectMode() {
		return ConnectMode.ACCEPT_ONE;
	}

	/* @Override */
	public TraceRmiHandler accept()
    {
		try {
			TraceRmiHandler handler = doAccept(this);
			close();
			return handler;
		}
		catch (Exception e) {
			close();
			if (cancelled) {
				throw new CancelledException();
			}
			plugin.listeners.invoke().acceptFailed(this, e);
			throw e;
		}
	}

	/* @Override */
	public bool isClosed() {
		return socket.isClosed();
	}

	/* @Override */
	public void close() {
		plugin.removeAcceptor(this);
		base.close();
	}

	/* @Override */
	public void cancel() {
		cancelled = true;
		close();
		plugin.listeners.invoke().acceptCancelled(this);
	}
}
